// Regenerate this file with prepare_assets.mjs after changing static files.
const VERSION='1.0.0';
const PREFIX='lexitrek-'+new URL(self.registration.scope).pathname.replace(/[^a-z0-9]/gi,'_')+'-';
const CACHE=PREFIX+VERSION;
const FILES=["./","./app.js","./content.json","./engine.js","./icon-192.png","./icon-512.png","./icon-maskable.png","./icon.svg","./index.html","./manifest.webmanifest","./storage.js","./style.css","./audio/u1-1.mp3","./audio/u1-2.mp3","./audio/u1-3.mp3","./audio/u1-4.mp3","./audio/u1-5.mp3","./audio/u1-6.mp3","./audio/u1-7.mp3","./audio/u1-8.mp3","./audio/u2-1.mp3","./audio/u2-2.mp3","./audio/u2-3.mp3","./audio/u2-4.mp3","./audio/u2-5.mp3","./audio/u2-6.mp3","./audio/u2-7.mp3","./audio/u2-8.mp3","./audio/u3-1.mp3","./audio/u3-2.mp3","./audio/u3-3.mp3","./audio/u3-4.mp3","./audio/u3-5.mp3","./audio/u3-6.mp3","./audio/u3-7.mp3","./audio/u3-8.mp3","./audio/u4-1.mp3","./audio/u4-2.mp3","./audio/u4-3.mp3","./audio/u4-4.mp3","./audio/u4-5.mp3","./audio/u4-6.mp3","./audio/u4-7.mp3","./audio/u4-8.mp3","./audio/u5-1.mp3","./audio/u5-2.mp3","./audio/u5-3.mp3","./audio/u5-4.mp3","./audio/u5-5.mp3","./audio/u5-6.mp3","./audio/u5-7.mp3","./audio/u5-8.mp3"];
const CORE=["./","./app.js","./content.json","./engine.js","./icon-192.png","./icon-512.png","./icon-maskable.png","./icon.svg","./index.html","./manifest.webmanifest","./storage.js","./style.css"];
const absolute=p=>new URL(p,self.registration.scope).href;
async function checkedFetch(url){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(url,{cache:'reload',signal:controller.signal});if(!r.ok||r.redirected)throw new Error('A resource could not be saved. Reconnect and retry.');const kind=r.headers.get('content-type')||'';const pathname=new URL(url).pathname;if(pathname.endsWith('.mp3')&&!kind.startsWith('audio/'))throw new Error('Pronunciation download is incomplete.');if((pathname.endsWith('.js')||pathname.endsWith('.json'))&&kind.includes('text/html'))throw new Error('Open LexiTrek while signed in, then prepare offline learning.');return r;}finally{clearTimeout(timer);}}
async function status(){const c=await caches.open(CACHE);let count=0;for(const f of FILES){if(await c.match(absolute(f)))count++;}return {ready:count===FILES.length,done:count,total:FILES.length,version:VERSION};}
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);for(const f of CORE){const url=absolute(f);await c.put(url,await checkedFetch(url));}await self.skipWaiting();})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('message',e=>{const port=e.ports[0];if(!port)return;e.waitUntil((async()=>{try{if(e.data.type==='STATUS'){port.postMessage(await status());return;}if(e.data.type!=='PREPARE')return;const cache=await caches.open(CACHE);let done=0;const queue=[...FILES];async function worker(){while(queue.length){const f=queue.shift(),url=absolute(f);if(!(await cache.match(url)))await cache.put(url,await checkedFetch(url));done++;port.postMessage({progress:Math.round(done/FILES.length*100),done,total:FILES.length});}}await Promise.all(Array.from({length:4},worker));port.postMessage(await status());}catch(error){port.postMessage({error:error.message||'The offline pack is incomplete.'});}})());});
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;e.respondWith((async()=>{const cache=await caches.open(CACHE);url.search='';const cached=await cache.match(url.href);if(cached)return cached;try{const response=await fetch(e.request);if(response.ok&&!response.redirected&&FILES.some(f=>absolute(f)===url.href))await cache.put(url.href,response.clone());return response;}catch{if(e.request.mode==='navigate'){const shell=await cache.match(absolute('./index.html'));if(shell)return shell;}return new Response('This resource is not saved offline yet.',{status:503,headers:{'Content-Type':'text/plain'}});}})());});
